Given a Binary Tree, the task is to print the diagonal traversal of the binary tree.Note: If the diagonal element are present in two different subtrees, then left subtree diagonal element should be taken first and then right subtree. Example:Input:  Output: 8 10 14 3 6 7 13 1 4Explanation: The above is the diagonal elements in a binary tree that belong to the same line.Try It YourselfUsing Recursion and Hashmap - O(n) Time and O(n) Space:To find the diagonal view of a binary tree, we perform a recursive  traversal that stores nodes in a hashmap based on their diagonal levels. Left children increase the diagonal level, while right children remain on the same level.Below is the implementation of the above approach:
            C++

    // C++ program to print diagonal view
#include <bits/stdc++.h>
using namespace std;

class Node {
  public:
    int data;
    Node *left, *right;
    Node(int x) {
        data = x;
        left = nullptr;
        right = nullptr;
    }
};

// Recursive function to print diagonal view
void diagonalRecur(Node *root, int level, 
                   unordered_map<int, vector<int>> &levelData) {

    // Base case
    if (root == nullptr)
        return;

    // Append the current node into hash map.
    levelData[level].push_back(root->data);

    // Recursively traverse the left subtree.
    diagonalRecur(root->left, level + 1, levelData);

    // Recursively traverse the right subtree.
    diagonalRecur(root->right, level, levelData);
}

// function to print diagonal view
vector<int> diagonal(Node *root) {
    vector<int> ans;

    // Create a hash map to store each
    // node at its respective level.
    unordered_map<int, vector<int>> levelData;
    diagonalRecur(root, 0, levelData);

    int level = 0;

    // Insert into answer level by level.
    while (levelData.find(level) != levelData.end()) {
        vector<int> v = levelData[level];
        for (int j = 0; j < v.size(); j++) {
            ans.push_back(v[j]);
        }
        level++;
    }

    return ans;
}

void printList(vector<int> v) {
    int n = v.size();
    for (int i = 0; i < n; i++) {
        cout << v[i] << " ";
    }
    cout << endl;
}

int main() {

    // Create a hard coded tree
    //         8
    //       /   \
    //     3      10
    //    /      /  \
    //   1      6    14
    //         / \   /
    //        4   7 13
    Node *root = new Node(8);
    root->left = new Node(3);
    root->right = new Node(10);
    root->left->left = new Node(1);
    root->right->left = new Node(6);
    root->right->right = new Node(14);
    root->right->right->left = new Node(13);
    root->right->left->left = new Node(4);
    root->right->left->right = new Node(7);

    vector<int> ans = diagonal(root);
    printList(ans);
}


            Java

    // Java program to print diagonal view
import java.util.*;

class Node {
    int data;
    Node left, right;

    Node(int x) {
        data = x;
        left = null;
        right = null;
    }
}

class GfG {

    // Recursive function to print diagonal view
    static void diagonalRecur( Node root, int level,
        		HashMap<Integer, ArrayList<Integer> > levelData) {

        // Base case
        if (root == null)
            return;

        // Append the current node into hash map.
        levelData.computeIfAbsent
          (level, k -> new ArrayList<>()).add(root.data);

        // Recursively traverse the left subtree.
        diagonalRecur(root.left, level + 1, levelData);

        // Recursively traverse the right subtree.
        diagonalRecur(root.right, level, levelData);
    }

    // function to print diagonal view
    static ArrayList<Integer> diagonal(Node root) {
        ArrayList<Integer> ans = new ArrayList<>();

        // Create a hash map to store each
        // node at its respective level.
        HashMap<Integer, ArrayList<Integer> > levelData = new HashMap<>();
        diagonalRecur(root, 0, levelData);

        int level = 0;

        // Insert into answer level by level.
        while (levelData.containsKey(level)) {
            ArrayList<Integer> v = levelData.get(level);
            ans.addAll(v);
            level++;
        }

        return ans;
    }

    static void printList(ArrayList<Integer> v) {
        for (int val : v) {
            System.out.print(val + " ");
        }
        System.out.println();
    }

    public static void main(String[] args) {

        // Create a hard coded tree
        //         8
        //       /   \
        //     3      10
        //    /      /  \
        //   1      6    14
        //         / \   /
        //        4   7 13
        Node root = new Node(8);
        root.left = new Node(3);
        root.right = new Node(10);
        root.left.left = new Node(1);
        root.right.left = new Node(6);
        root.right.right = new Node(14);
        root.right.right.left = new Node(13);
        root.right.left.left = new Node(4);
        root.right.left.right = new Node(7);

        ArrayList<Integer> ans = diagonal(root);
        printList(ans);
    }
}


